#!/usr/bin/env bash
# SO LEITURA -- investiga o unico ENCAIXE DIFERENTE da sombra do catalogo (dia 1): anuncio IPI-CRD-3-E-V4, recebido
# 21/11 19:20, V1.0 pos em Q06, a V1.1 disse SEM VAGA. Mostra datas, se a reserva foi casada e quem ocupa cada
# candidata nas mesmas noites (ids embaralhados). Nenhum nome, codigo HM, valor, telefone ou e-mail. Nada e gravado.
set -u
exec 2>&1
cd /opt/PMS-Banana-AI/SISTEMA/api || exit 1
sudo -n /opt/esteira-nuvem/com-segredos env PMS_TRANSCRICAO_AQUECER=off PYTHONDONTWRITEBYTECODE=1 timeout 300 ../.venv/bin/python -u - <<'PY' 2>&1 | grep -vE '^(WARNING|INFO|DEBUG)'
import base64, hashlib, json, types
from datetime import date
def modulo(nome, b):
    m = types.ModuleType(nome); exec(compile(base64.b64decode(b).decode(), nome, "exec"), m.__dict__); return m
C11 = modulo("v11_catalogo", "")
CAT = C11.validar(json.loads(base64.b64decode("").decode()))
from app.main import build_state
from app.entrada import airbnb_reservas as R10
from app.entrada.intents import casar
s = build_state().store
h = lambda x: hashlib.sha256(str(x).encode()).hexdigest()[:8]
for row in (getattr(s, "entradas", {}) or {}).values():
    p = row.get("plano") or {}
    if str(p.get("anuncio_id")) != "1803453366539675992" or not str(row.get("recebido_em") or "").startswith("2026-11-21T19:2"): continue
    res = casar(s, p.get("codigo") or "")
    print("entrada: acao", p.get("acao"), "| unidade V1.0", p.get("unidade"), "| checkin", p.get("checkin"), "| checkout", p.get("checkout"), "| hospedes", p.get("hospedes"))
    print("reserva casada na V1.0:", res is not None, "| id", h(res.reservation_id) if res is not None else "-",
          "| estado", getattr(res, "status", getattr(res, "estado", "?")) if res is not None else "-",
          "| unidade", getattr(res, "unit", getattr(res, "unidade", "?")) if res is not None else "-")
    ci, co = date.fromisoformat(p["checkin"]), date.fromisoformat(p["checkout"])
    prod = C11.resolver(CAT, "airbnb", str(p.get("anuncio_id")))
    cand = C11.candidatas(CAT, prod, p.get("hospedes"))
    print("produto V1.1:", prod["codigo"], "| candidatas:", cand)
    sem = res.reservation_id if res is not None else ""
    for u in cand:
        oc = R10.ocupantes(s, u, ci, co, sem=sem)
        print(" ", u, "ocupantes:", len(oc or []))
        for o in (oc or [])[:5]:
            rid = getattr(o, "reservation_id", o if isinstance(o, str) else "?")
            print("    id", h(rid), "| mesma reserva:", rid == sem, "|", getattr(o, "check_in", "?"), "->", getattr(o, "check_out", "?"),
                  "| estado", getattr(o, "status", "?"), "| tipo", type(o).__name__)
PY
echo "fim"
